"""DGP4 supervised runner (derived from run_dgp3.py; DGP4 arms) (protocol rule 4): every arm executes from a CLEAN DETACHED CHECKOUT at the frozen commit (--code-root), with the worker's cwd set to that checkout, source identity checked at launch and at completion
(sha256 of the planner / engine / kernel files vs FREEZE.json), outputs under the records tree (outside tracked source). Arms: BASE (accepted integrated.py with run_paired.FROZEN options), REPAIRED (unified_pac_planner v0.8 --lifted --envelope G2: DGP3 FULL3 + repairs R1-R3),
NEW (--lifted --envelope RMAX), and the diagnostic pseudo-arms FORCED_G2 / FORCED_RMAX (--force-stream lifted; never counted as planner completions). Sample seed per task: first eight SHA-256 bytes of 'DGP4-SAMPLE|<model_sha256>|<k>' reduced to 1..2^31-1 (k = 0 primary, 1 / 2 confirmations), shared across arms. Contracts: main 20.0 / 19.5 / 19.0; p4 4.0 / 3.85 / 3.5; p20 = main.
usage: run_dgp4.py SUBDIR MANIFEST.json --code-root /path/to/detached --arms BASE,REPAIRED,NEW --contract main|p4|p20 [--confirm --seed-index K] [--only a,b] [--scope S] [--records RD]"""
import sys, os, json, time, subprocess, argparse, hashlib
RD_DEFAULT = '/Users/adis/Workspace/pgm-records/code/runs/mdi_2026-10-28/DGP4_RESIDUAL_MAX'; SUP_CODE = '/Users/adis/Workspace/pgm/code'; PY = os.path.join(SUP_CODE, '.venv/bin/python')
CONTRACTS = dict(main=dict(outer=20.0, hard=19.5, work=19.0), p4=dict(outer=4.0, hard=3.85, work=3.5), p20=dict(outer=20.0, hard=19.5, work=19.0))
FROZEN = dict(mem_gib=3, epsilon='1/200', delta='1/1000000', base=dict(route='auto', proposal='mb', schedule='targeted', table_cap=1 << 18, enum_cap=1 << 16, mb_cap=1 << 24, batch=1024), contracts=CONTRACTS)
IDENTITY_FILES = ['cex/hp/unified_pac_planner.py', 'cex/hp/pac_actions.py', 'cex/hp/lifted_decoder.py', 'cex/hp/grouped_envelope.py', 'cex/hp/residual_max_envelope.py', 'cex/hp/unified_planner.py', 'cex/hp/coarse_envelope.py', 'cex/hp/cost_model.py', 'cex/hp/PHASE_RATES_R1.json', 'cex/blockres/integrated.py', 'cex/blockres/blockres.py', 'cex/newarm/cex_executor.py', 'cex/newarm/cex_kernel.cpp', 'cex/newarm/libcex_kernel.dylib', 'cex/newarm/cex_build.json']
def sha(p): return hashlib.sha256(open(p, 'rb').read()).hexdigest()
def identity(code_root): return {f: sha(os.path.join(code_root, 'code', f)) for f in IDENTITY_FILES}

def cmd_of(arm, model, out, c, seed, root):
    b = FROZEN['base']; code = os.path.join(root, 'code')
    if arm == 'BASE': return [PY, os.path.join(code, 'cex/blockres/integrated.py'), '--input', model, '--output', out, '--budget', str(c['hard']), '--mb-cap', str(b['mb_cap']), '--table-cap', str(b['table_cap']), '--enum-cap', str(b['enum_cap']), '--schedule', b['schedule'], '--route', b['route'], '--proposal', b['proposal'], '--batch', str(b['batch']), '--seed', str(seed), '--epsilon', FROZEN['epsilon'], '--delta', FROZEN['delta']]
    base = [PY, os.path.join(code, 'cex/hp/unified_pac_planner.py'), '--input', model, '--output', out, '--budget', str(c['hard']), '--admission-stop', str(c['work']), '--epsilon', FROZEN['epsilon'], '--delta', FROZEN['delta'], '--seed', str(seed)]
    return base + {'REPAIRED': ['--lifted', '--envelope', 'G2'], 'NEW': ['--lifted', '--envelope', 'RMAX'], 'FORCED_G2': ['--force-stream', 'lifted', '--envelope', 'G2'], 'FORCED_RMAX': ['--force-stream', 'lifted', '--envelope', 'RMAX']}[arm]

def sample_seed(model_sha256, k):
    """the frozen sample-seed rule (PROTOCOL section 3): first eight SHA-256 bytes of 'DGP4-SAMPLE|<model_sha256>|<k>' as an unsigned big-endian integer, reduced to the CLI's domain 1..2^31-1"""
    x = int.from_bytes(hashlib.sha256(('DGP4-SAMPLE|%s|%d' % (model_sha256, k)).encode('utf-8')).digest()[:8], 'big'); return (x % ((1 << 31) - 1)) + 1

def last_receipt(ledger, job):
    rows = [json.loads(l) for l in open(ledger)]; r = [x for x in rows if x.get('kind') == 'RECEIPT' and x['job'] == job]; return r[-1] if r else None

def summarize(arm, out, rc, c):
    from fractions import Fraction as F
    row = dict(receipt_wall_s=(rc['wall_s'] if rc else None), receipt_outcome=(rc['outcome'] if rc else None), peak_MiB=((rc['peak_tree_rss_bytes'] / 2 ** 20) if rc and rc.get('peak_tree_rss_bytes') else None))
    try:
        d = json.load(open(out)); m = d.get('mechanism') or {}
        row.update(outcome=d.get('outcome'), guarantee=d.get('guarantee'), published=d.get('published'), K=d.get('K'), solver_wall_s=d.get('wall_s'), termination=m.get('termination'), route=m.get('route'), peak_rss_bytes=d.get('peak_rss_bytes'), positive_mass_witness=(d.get('positive_mass_witness') if arm == 'BASE' else m.get('positive_mass_witness')), hard_deadline_respected=d.get('hard_deadline_respected'), version=(d.get('version') or '')[:60])
        rows_ = d.get('answers') or []; ws = [float(F(r['hi']) - F(r['lo'])) / 2 for r in rows_ if r['guarantee'] != 'NOT_PUBLISHED']
        if arm == 'BASE': row.update(base=dict(draws=m.get('draws'), Kq=m.get('Kq'), remaining=m.get('remaining'), max_remaining_width=m.get('max_remaining_width'), median_remaining_width=m.get('median_remaining_width'), X_mean=m.get('X_mean'), ESS=m.get('ESS'), zero_weight_fraction=m.get('zero_weight_fraction'), largest_share=m.get('largest_share'), eps_num=m.get('eps_num'), mb_cap=m.get('mb_cap'), mb_splits=m.get('mb_splits'), batch_used=m.get('batch_used'), deadline_phase=d.get('deadline_phase'), refusal=d.get('refusal'), trace=d.get('trace'), phases=d.get('phases_s'), structural={k: (m.get(k) or {}).get('status') for k in ('evidence_expansion', 'layered_contraction', 'ancestral_response', 'support_closure')}), radius_report=dict(worst=(max(ws) if ws else None), covered_at_eps=sum(1 for w in ws if w <= 0.005), published=len(ws), K=d.get('K')))
        else: row.update(upac=dict(streams=[{k: s.get(k) for k in ('kind', 'label', 'stage', 'closed', 'delta_s', 'scale_to_original', 'Z_original', 'draws', 'zero_draws', 'batches', 'abandoned', 'checkpoints', 'witness', 'published', 'K', 't_prep', 't_sample', 't_cert', 'X_mean', 'zero_weight_fraction', 'ESS_DIAGNOSTIC', 'largest_share', 'max_log2_X_observed', 'max_remaining_width', 'retained_bytes')} | dict(valid_endpoints=(s.get('trace') or [{}])[-1].get('valid_endpoints') if s.get('trace') else None, mechanism={k: v for k, v in (s.get('mechanism') or {}).items() if k in ('eps_num', 'rho_cap', 'rho_X', 'alpha_per_coordinate', 'cap_log2_total', 'cap_units', 'grouped_envelope', 'rmax', 'rmax_refusal', 'rmax_allowance', 'bound_kind', 'kappa_compact', 'kappa_log2_hi', 'mb_cap', 'mb_splits', 'Kq', 'batch_used', 'terminal', 'exact_route', 'memory_policy', 'proposal_immutable', 'coarse_cards', 'widening', 'widening_parts', 'certificate_defect', 'const_log2')}, trace=s.get('trace'), measurements=[x for x in (s.get('measurements') or []) if x.get('kind') in ('pac_stage', 'lifted_stage')]) for s in d.get('streams', [])], risk_ledger=d.get('risk_ledger'), conflicts=d.get('conflicts'), checkpoints=d.get('checkpoints'), radius_report=d.get('radius_report'), cost_breakdown=d.get('cost_breakdown'), decisions=[x.get('chosen') for x in d.get('decisions', [])], E=m.get('exploration_account_s'), E_used=m.get('exploration_used_s'), refusal=m.get('refusal'), defect=m.get('defect'), structural=m.get('structural_info'), representations_solved=m.get('representations_solved'), native_attempts=m.get('native_attempts'), live_memory=m.get('live_memory_named_bytes'), lift_only=m.get('lift_only_candidates'), forced=d.get('forced_stream')), radius_report=d.get('radius_report'))
    except Exception as e: row.update(outcome='NO_RESULT_FILE', error=repr(e)[:200])
    row['complete'] = bool(rc and rc['outcome'] == 'COMPLETED' and rc['wall_s'] <= c['outer'] and row.get('published') is not None and row.get('K') and row['published'] == row['K'] and row.get('outcome') in ('COMPLETE', 'EXACT') and bool(row.get('positive_mass_witness')) and (row.get('hard_deadline_respected') is not False)) and arm not in ('FORCED_G2', 'FORCED_RMAX')
    return row

def main():
    ap = argparse.ArgumentParser(); ap.add_argument('sub'); ap.add_argument('manifest'); ap.add_argument('--code-root', required=True); ap.add_argument('--arms', default='BASE,REPAIRED,NEW'); ap.add_argument('--contract', default='main', choices=list(CONTRACTS)); ap.add_argument('--confirm', action='store_true'); ap.add_argument('--seed-index', type=int, default=0, help='k in DGP4-SAMPLE|<model_sha256>|<k>: 0 primary, 1 / 2 confirmations'); ap.add_argument('--only', default=None); ap.add_argument('--scope', default='dgp4_main'); ap.add_argument('--records', default=RD_DEFAULT); ap.add_argument('--freeze', default=None); a = ap.parse_args()
    RD = a.records; man = json.load(open(a.manifest)); tasks = man['tasks']; arms = a.arms.split(','); c = CONTRACTS[a.contract]; env = dict(os.environ, OMP_NUM_THREADS='1', OPENBLAS_NUM_THREADS='1', MKL_NUM_THREADS='1', VECLIB_MAXIMUM_THREADS='1'); env.pop('PYTHONPATH', None); results = []; ledger = os.path.join(RD, 'DGP4_LEDGER.jsonl')
    root = os.path.abspath(a.code_root); head = subprocess.check_output(['git', '-C', root, 'rev-parse', 'HEAD']).decode().strip(); tree = subprocess.check_output(['git', '-C', root, 'rev-parse', 'HEAD^{tree}']).decode().strip(); dirty = subprocess.check_output(['git', '-C', root, 'status', '--porcelain', '--untracked-files=no', '--', 'code/cex', 'code/gbidi']).decode().strip()
    frozen = json.load(open(a.freeze or os.path.join(RD, 'FREEZE.json'))); ident0 = identity(root); assert head == frozen['code']['commit'], 'code root %s is not at the frozen commit %s' % (head, frozen['code']['commit']); assert not dirty, 'code root has tracked changes: %s' % dirty[:200]; assert all(ident0[f] == frozen['code']['files'].get(f) for f in ident0), 'identity mismatch vs FREEZE.json at launch: %s' % [f for f in ident0 if ident0[f] != frozen['code']['files'].get(f)]      # the ARM identity files (planner / engine / kernel); FREEZE.json also lists the harness scripts
    kb = json.load(open(os.path.join(root, 'code/cex/newarm/cex_build.json'))); assert kb['binary_sha256'] == sha(os.path.join(root, 'code/cex/newarm/libcex_kernel.dylib')), 'kernel binary does not match its build record'
    for i, t in enumerate(tasks):
        if a.only and t['name'] not in a.only.split(','): continue
        r = i % len(arms); order = arms[r:] + arms[:r]
        if a.confirm: order = order[::-1]
        seed = sample_seed(t['model_sha256'], a.seed_index)
        for arm in order:
            tag = ('c%d' % a.seed_index) if a.confirm else ('p' if a.seed_index == 0 else 's%d' % a.seed_index); attempt = os.path.join(RD, a.sub, '%02d__%s__%s__%s' % (i, t['name'], arm, tag)); os.makedirs(attempt, exist_ok=True); out = os.path.join(attempt, 'result.json'); cmd = cmd_of(arm, t['model'], out, c, seed, root); job = 'dgp4:%s:%s:%s:%s' % (a.sub, t['name'], arm, tag)
            ident_launch = identity(root)
            sup = [PY, '-m', 'gbidi.supervise', '--ledger', ledger, '--scope', a.scope, '--job', job, '--timeout', str(c['outer']), '--mem-gib', str(FROZEN['mem_gib']), '--interval', '0.05', '--cwd', os.path.join(root, 'code'), '--stdout', os.path.join(attempt, 'stdout.txt'), '--stderr', os.path.join(attempt, 'stderr.txt'), '--', '/usr/bin/caffeinate', '-s'] + cmd
            subprocess.run(sup, cwd=SUP_CODE, env=env); rc = last_receipt(ledger, job); ident_done = identity(root)
            row = dict(task=t['name'], arm=arm, task_index=i, order_index=order.index(arm), confirm=a.confirm, seed=seed, seed_index=a.seed_index, seed_rule='DGP4-SAMPLE|<model_sha256>|<k> -> first 8 SHA-256 bytes big-endian -> (x mod (2^31 - 1)) + 1', contract=a.contract, panel=t.get('panel'), family=t.get('family') or t.get('topology'), model=t['model'], model_sha256=t.get('model_sha256'), evid_sha256=t.get('evid_sha256'), model_sha256_at_run=sha(t['model']), code_commit=head, code_tree=tree, identity_ok=all(ident_launch[f] == frozen['code']['files'].get(f) == ident_done[f] for f in ident_launch), command=' '.join(cmd), job=job); row.update(summarize(arm, out, rc, c)); results.append(row)
            json.dump(dict(cell=row, identity_at_launch=ident_launch, identity_at_completion=ident_done), open(os.path.join(attempt, 'cell.json'), 'w'), indent=1, default=str)
            print(json.dumps({k: row.get(k) for k in ('task', 'arm', 'outcome', 'published', 'K', 'receipt_wall_s', 'receipt_outcome', 'complete', 'termination', 'identity_ok')}, default=str), flush=True)
            json.dump(dict(frozen=FROZEN, arms=arms, contract=a.contract, manifest=a.manifest, code_root=root, code_commit=head, code_tree=tree, confirm=a.confirm, seed_index=a.seed_index, only=a.only, results=results, utc=time.strftime('%Y-%m-%dT%H:%M:%SZ', time.gmtime())), open(os.path.join(RD, a.sub, 'RESULTS_%s_%s%s.json' % (a.contract, ('confirm_s%d' % a.seed_index) if a.confirm else ('s%d' % a.seed_index if a.seed_index != 0 else 'primary'), ('_' + a.only.replace(',', '_')[:60]) if a.only else '')), 'w'), indent=1, default=str)

if __name__ == '__main__': main()
